def main():
    seed_path = pathlib.Path(__file__).parent / "seed" / "styles_seed.json"
    rows = json.loads(seed_path.read_text())
    for row in rows:
        sid = row["id"]
        i18n = row.setdefault("i18n", {})
        for lang, md in T.get(sid, {}).items():
            i18n.setdefault(lang, {})["description_md"] = md
    seed_path.write_text(json.dumps(rows, indent=2, ensure_ascii=False) + "\n")
    langs = sorted({k for s in rows for k in (s.get("i18n") or {}).keys()})
    print(f"Wrote {len(rows)} styles, each with up to {len(langs)} i18n languages")
    print("langs:", langs)


if __name__ == "__main__":
    main()
